create extension if not exists pgcrypto;
create table if not exists players (telegram_user_id bigint primary key, username text, display_name text not null, first_seen timestamptz not null default now(), last_seen timestamptz not null default now());
create table if not exists games (game_key text primary key, title text not null, short_name text not null unique, active boolean not null default true);
insert into games values ('doodle_covert','Doodle Covert','doodle_covert',true) on conflict (game_key) do update set title=excluded.title;
create table if not exists game_sessions (jti uuid primary key, telegram_user_id bigint references players, game_key text references games, chat_id bigint, message_id bigint, inline_message_id text, created_at timestamptz not null default now());
create table if not exists game_scores (id uuid primary key default gen_random_uuid(), telegram_user_id bigint references players, game_key text references games, score integer not null check(score>=0), won boolean not null, sector integer not null, intel integer not null, time_seconds real not null, detections integer not null, created_at timestamptz not null default now());
create table if not exists player_bests (telegram_user_id bigint references players, game_key text references games, best_score integer not null default 0, total_runs integer not null default 0, total_wins integer not null default 0, updated_at timestamptz not null default now(), primary key(telegram_user_id,game_key));
create table if not exists feedback (id uuid primary key default gen_random_uuid(), telegram_user_id bigint, game_key text not null, message text not null check(char_length(message)<=2000), status text not null default 'new', created_at timestamptz not null default now());
create or replace view leaderboard as select b.game_key,p.display_name,b.best_score from player_bests b join players p using(telegram_user_id);
alter table players enable row level security; alter table games enable row level security; alter table game_sessions enable row level security; alter table game_scores enable row level security; alter table player_bests enable row level security; alter table feedback enable row level security;
